local IngotMoldMaker = {}
local PRODUCTS = {
    iron_ingot_mold = { name = "Železni model za palice", ironCost = 4, woodCost = 1, leatherCost = 1, time = 5, cost = 180, prestige = 4, happiness = 2, description = "Železni model za litje kovinskih palic." },
    bronze_ingot_mold = { name = "Bronast model za palice", bronzeCost = 4, ironCost = 1, woodCost = 1, leatherCost = 1, time = 7, cost = 435, prestige = 6, happiness = 3, description = "Bronast model za standardne palice." },
    silver_ingot_mold = { name = "Srebrni model za palice", silverCost = 4, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 1, time = 11, cost = 1050, prestige = 11, happiness = 4, description = "Srebrni model za plemiške palice." },
    gilded_ingot_mold = { name = "Pozlačeni model za palice", goldCost = 1, silverCost = 4, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 15, cost = 2250, prestige = 20, happiness = 5, description = "Pozlačeni model za dvorne palice." },
    jewel_set_ingot_mold = { name = "Draguljasti model za palice", goldCost = 2, silverCost = 4, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 19, cost = 4850, prestige = 36, happiness = 7, description = "Draguljasti model za kraljevske palice." },
    royal_sovereign_ingot_mold = { name = "Kraljevski suvereni model za palice", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 26, cost = 10400, prestige = 68, happiness = 13, description = "Suvereni model za palice z biseri za krono." },
}
local BUILDINGS = {
    ingotmold_workshop = { name = "Palična delavnica", cost = { gold = 355, wood = 175, stone = 140, iron = 9 }, upkeep = 7, qualityBonus = 5 },
    ingotmold_house = { name = "Palična hiša", cost = { gold = 1255, wood = 360, stone = 280, silver = 7, iron = 8 }, upkeep = 26, qualityBonus = 18 },
    master_ingotmold_atelier = { name = "Mojstrski palični atelje", cost = { gold = 3140, wood = 420, stone = 535, silver = 37, gold = 7 }, upkeep = 74, qualityBonus = 30 },
    sovereign_ingotmold_palace = { name = "Suverena palična palača", cost = { gold = 13300, wood = 650, stone = 845, gold = 85, jewel = 19 }, upkeep = 260, qualityBonus = 55, prestigeBonus = 50 },
}
IngotMoldMaker.ironStock = 16; IngotMoldMaker.bronzeStock = 14; IngotMoldMaker.woodStock = 10; IngotMoldMaker.leatherStock = 8; IngotMoldMaker.silverStock = 8; IngotMoldMaker.goldStock = 6; IngotMoldMaker.jewelStock = 4; IngotMoldMaker.pearlStock = 4
IngotMoldMaker.productStock = {}; IngotMoldMaker.buildings = {}; IngotMoldMaker.maker = nil; IngotMoldMaker.activeMaking = {}; IngotMoldMaker.totalProducts = 0; IngotMoldMaker.dayTimer = 0
function IngotMoldMaker.init() IngotMoldMaker.ironStock=16; IngotMoldMaker.bronzeStock=14; IngotMoldMaker.woodStock=10; IngotMoldMaker.leatherStock=8; IngotMoldMaker.silverStock=8; IngotMoldMaker.goldStock=6; IngotMoldMaker.jewelStock=4; IngotMoldMaker.pearlStock=4; IngotMoldMaker.productStock={}; IngotMoldMaker.buildings={}; IngotMoldMaker.maker=nil; IngotMoldMaker.activeMaking={}; IngotMoldMaker.totalProducts=0; IngotMoldMaker.dayTimer=0; print("[IngotMoldMaker] Royal Ingot Mold Maker System initialized (6 products, 4 buildings)") end
function IngotMoldMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; IngotMoldMaker.maker={name=n or ("Paličar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Paličar najet: %s (spretnost: %d)",IngotMoldMaker.maker.name,s),"success") end; return true end
function IngotMoldMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function IngotMoldMaker.build(id) local ok,e=IngotMoldMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(IngotMoldMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function IngotMoldMaker.getQualityBonus() local b=0; for _,bd in ipairs(IngotMoldMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function IngotMoldMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and IngotMoldMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and IngotMoldMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and IngotMoldMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and IngotMoldMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and IngotMoldMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and IngotMoldMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and IngotMoldMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and IngotMoldMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #IngotMoldMaker.buildings==0 then return false,"Potrebna palična delavnica" end; if not IngotMoldMaker.maker then return false,"Potreben paličar" end; return true end
function IngotMoldMaker.make(pt,qty) qty=qty or 1; local ok,e=IngotMoldMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then IngotMoldMaker.ironStock=IngotMoldMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then IngotMoldMaker.bronzeStock=IngotMoldMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then IngotMoldMaker.woodStock=IngotMoldMaker.woodStock-d.woodCost*qty end; if d.leatherCost then IngotMoldMaker.leatherStock=IngotMoldMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then IngotMoldMaker.silverStock=IngotMoldMaker.silverStock-d.silverCost*qty end; if d.goldCost then IngotMoldMaker.goldStock=IngotMoldMaker.goldStock-d.goldCost*qty end; if d.jewelCost then IngotMoldMaker.jewelStock=IngotMoldMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then IngotMoldMaker.pearlStock=IngotMoldMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if IngotMoldMaker.maker then t=math.max(1,t-math.floor(IngotMoldMaker.maker.skill/13)) end; table.insert(IngotMoldMaker.activeMaking,{id="ingotmold_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function IngotMoldMaker.completeMaking(m) local q=1.0+(IngotMoldMaker.getQualityBonus()/100); if IngotMoldMaker.maker then q=q+(IngotMoldMaker.maker.skill/140) end; q=math.min(2.5,q); IngotMoldMaker.productStock[m.productType]=(IngotMoldMaker.productStock[m.productType] or 0)+m.quantity; IngotMoldMaker.totalProducts=IngotMoldMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if IngotMoldMaker.maker then IngotMoldMaker.maker.itemsMade=IngotMoldMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then IngotMoldMaker.maker.skill=math.min(100,IngotMoldMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Model za palice izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"ingotmold.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function IngotMoldMaker.update(dt) if not _G.state then return end; IngotMoldMaker.dayTimer=IngotMoldMaker.dayTimer+dt; if IngotMoldMaker.dayTimer>=30 then IngotMoldMaker.dayTimer=0; for i=#IngotMoldMaker.activeMaking,1,-1 do local m=IngotMoldMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then IngotMoldMaker.completeMaking(m); table.remove(IngotMoldMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(IngotMoldMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if IngotMoldMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function IngotMoldMaker.getStats() return {ironStock=IngotMoldMaker.ironStock,bronzeStock=IngotMoldMaker.bronzeStock,woodStock=IngotMoldMaker.woodStock,leatherStock=IngotMoldMaker.leatherStock,silverStock=IngotMoldMaker.silverStock,goldStock=IngotMoldMaker.goldStock,jewelStock=IngotMoldMaker.jewelStock,pearlStock=IngotMoldMaker.pearlStock,productStock=IngotMoldMaker.productStock,numBuildings=#IngotMoldMaker.buildings,hasMaker=IngotMoldMaker.maker~=nil,makerName=IngotMoldMaker.maker and IngotMoldMaker.maker.name or "—",makerSkill=IngotMoldMaker.maker and IngotMoldMaker.maker.skill or 0,activeMaking=#IngotMoldMaker.activeMaking,totalProducts=IngotMoldMaker.totalProducts} end
return IngotMoldMaker
